165	// resolveImports records the local name of net/http and crypto/tls, alias
166	// included, and reports a dot import of either.
167	func (s *scanner) resolveImports(f *ast.File) {
168		for _, imp := range f.Imports {
169			p, err := strconv.Unquote(imp.Path.Value)
170			if err != nil || (p != guardHTTPPath && p != guardTLSPath) {
171				continue
172			}
173			if p == guardHTTPPath {
174				s.importsHT = true
175			}
176			local := path.Base(p)
177			if imp.Name != nil {
178				local = imp.Name.Name
179			}
180			switch local {
181			case "_":
182				continue
183			case ".":
184				s.add(imp.Pos(), ruleDotImport, "import")
185				continue
186			}
187			s.names[local] = p
188		}
189	}
