195	// isSel reports whether e is pkg.Name for the imported package at pkgPath, under
196	// whatever local name the file gave it; with no names, any selector of it.
197	func (s *scanner) isSel(e ast.Expr, pkgPath string, names ...string) bool {
198		sel, ok := e.(*ast.SelectorExpr)
199		if !ok {
200			return false
201		}
202		id, ok := sel.X.(*ast.Ident)
203		if !ok || s.names[id.Name] != pkgPath {
204			return false
205		}
206		return len(names) == 0 || slices.Contains(names, sel.Sel.Name)
207	}
208	
209	// valueOfType reports a type expression that builds a transport or a dialer by
210	// value: http.Transport (R1) or tls.Dialer (R4).
211	func (s *scanner) valueOfType(typ ast.Expr, pos token.Pos, fn string) {
212		switch {
213		case s.isSel(typ, guardHTTPPath, "Transport"):
214			s.add(pos, "R1", fn)
215		case s.isSel(typ, guardTLSPath, "Dialer"):
216			s.add(pos, "R4", fn)
217		}
218	}
219	
220	// inspect walks one top-level declaration; closures belong to the declaration
221	// that holds them.
222	func (s *scanner) inspect(node ast.Node, fn string) {
223		ast.Inspect(node, func(n ast.Node) bool {
224			switch n := n.(type) {
225			case *ast.CompositeLit:
226				if n.Type != nil {
227					s.valueOfType(n.Type, n.Pos(), fn)
228				}
229			case *ast.CallExpr:
230				if id, ok := n.Fun.(*ast.Ident); ok && id.Name == "new" && len(n.Args) == 1 {
231					s.valueOfType(n.Args[0], n.Pos(), fn)
232				}
233			case *ast.ValueSpec:
234				if n.Type != nil {
235					s.valueOfType(n.Type, n.Pos(), fn)
236				}
237			case *ast.SelectorExpr:
238				if s.isSel(n, guardHTTPPath, "DefaultTransport") {
239					s.add(n.Pos(), "R2", fn)
240				}
241				if s.isSel(n, guardTLSPath, "Dial", "DialWithDialer", "Client") {
242					s.add(n.Pos(), "R4", fn)
243				}
244			case *ast.AssignStmt:
245				if s.importsHT && n.Tok == token.ASSIGN {
246					for _, lhs := range n.Lhs {
247						if sel, ok := lhs.(*ast.SelectorExpr); ok && sel.Sel.Name == "Proxy" {
248							s.add(n.Pos(), "R3", fn)
249						}
250					}
251				}
252			case *ast.KeyValueExpr:
253				if id, ok := n.Key.(*ast.Ident); ok && s.importsHT && id.Name == "Proxy" {
254					s.add(n.Pos(), "R3", fn)
255				}
256			}
257			return true
258		})
259	}
