261	// funcName is "Func" or "Type.Method", without the pointer or the type
262	// parameters of the receiver.
263	func funcName(d *ast.FuncDecl) string {
264		if d.Recv == nil || len(d.Recv.List) == 0 {
265			return d.Name.Name
266		}
267		return receiverName(d.Recv.List[0].Type) + "." + d.Name.Name
268	}
269	
270	func receiverName(e ast.Expr) string {
271		switch t := e.(type) {
272		case *ast.StarExpr:
273			return receiverName(t.X)
274		case *ast.ParenExpr:
275			return receiverName(t.X)
276		case *ast.IndexExpr:
277			return receiverName(t.X)
278		case *ast.IndexListExpr:
279			return receiverName(t.X)
280		case *ast.Ident:
281			return t.Name
282		}
283		return ""
284	}
