286	// findModuleRoot goes up from dir to the first directory that holds a go.mod.
287	// Inside a worktree that is the worktree's own go.mod, not the main checkout's.
288	func findModuleRoot(dir string) (string, error) {
289		dir, err := filepath.Abs(dir)
290		if err != nil {
291			return "", err
292		}
293		for {
294			if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
295				return dir, nil
296			}
297			parent := filepath.Dir(dir)
298			if parent == dir {
299				return "", fmt.Errorf("no go.mod above %s", dir)
300			}
301			dir = parent
302		}
303	}
