381	// Criterion 5: no production code builds its own path to the network outside
382	// the proxy entry point, but for the listed exceptions.
383	func TestNoHTTPClientBypassesTheProxyEntryPoint(t *testing.T) {
384		_, vs := scanRepo(t)
385		for _, v := range vs {
386			if !slices.ContainsFunc(proxyExceptions, func(e exception) bool { return e.covers(v) }) {
387				t.Errorf("%s: bypasses internal/netproxy; use netproxy.NewTransport, Dialer.DialTLS or a client without a Transport, or add a reasoned exception to proxyExceptions and to docs/architecture/network.md", v)
388			}
389		}
390	}
