392	// An exception that matches nothing is stale: the code moved or was fixed, and
393	// the list (and the doc) must follow.
394	func TestEveryProxyExceptionStillMatches(t *testing.T) {
395		_, vs := scanRepo(t)
396		seen := map[exception]bool{}
397		for _, e := range proxyExceptions {
398			key := exception{File: e.File, Func: e.Func, Rule: e.Rule}
399			if seen[key] {
400				t.Errorf("exception %s %s %s is listed twice", e.File, e.Func, e.Rule)
401			}
402			seen[key] = true
403			if !slices.Contains(guardRules, e.Rule) {
404				t.Errorf("exception %s %s: rule %q is not one of %v", e.File, e.Func, e.Rule, guardRules)
405			}
406			if strings.TrimSpace(e.Why) == "" || strings.TrimSpace(e.Until) == "" {
407				t.Errorf("exception %s %s %s needs a reason and an end (\"permanent\" or a story)", e.File, e.Func, e.Rule)
408			}
409			if !slices.ContainsFunc(vs, e.covers) {
410				t.Errorf("stale exception: %s %s %s matches no violation any more; remove it from proxyExceptions and docs/architecture/network.md", e.File, e.Func, e.Rule)
411			}
412		}
413	}
