707	// proxyDocSection is the part of the document under the heading that names the
708	// proxy entry point, up to the next heading of the same or a higher level.
709	func proxyDocSection(md string) (string, bool) {
710		heading := regexp.MustCompile(`^(#+)\s`)
711		var out []string
712		level := 0
713		for _, line := range strings.Split(md, "\n") {
714			if m := heading.FindStringSubmatch(line); m != nil {
715				switch {
716				case level == 0 && strings.Contains(strings.ToLower(line), "proxy entry point"):
717					level = len(m[1])
718				case level != 0 && len(m[1]) <= level:
719					return strings.Join(out, "\n"), true
720				}
721			}
722			if level != 0 {
723				out = append(out, line)
724			}
725		}
726		return strings.Join(out, "\n"), level != 0
727	}
