731		got, ok := proxyDocSection(md)
732		if !ok || !strings.Contains(got, "a.go") || !strings.Contains(got, "in sub") ||
733			strings.Contains(got, "not this") {
734			t.Errorf("proxyDocSection = %q, %v", got, ok)
735		}
736		if _, ok := proxyDocSection("# Network\n## Other\n"); ok {
737			t.Error("a document without the heading reported a section")
738		}
739	}
