20	// DEVDESK-581: the guard that keeps every connection DevDesk opens on the
21	// proxy entry point. It parses the production sources of the module (go/ast, no
22	// type information) and reports the four ways code has found to leave the path
23	// that net/http and this package share:
24	//
25	//	R1  an http.Transport built by hand (a literal, &literal, new(...) or a var)
26	//	R2  a reference to http.DefaultTransport (cloning it keeps its Proxy field
27	//	    but invites the next line to replace it)
28	//	R3  an assignment to a Proxy field, or a Proxy: key in a composite literal,
29	//	    in a file that imports net/http
30	//	R4  a raw TLS dial: tls.Dial, tls.DialWithDialer, tls.Client, tls.Dialer{}
31	//
32	// A new connection goes through Dialer.DialTLS, NewTransport or a client with no
33	// Transport (which uses http.DefaultTransport and so the proxy environment).
34	// What the guard cannot see is documented in docs/architecture/network.md.
35	
36	const (
37		guardHTTPPath = "net/http"
38		guardTLSPath  = "crypto/tls"
39	
40		// ruleDotImport is not one of R1 to R4 and cannot be excepted: a dot import
41		// of net/http or crypto/tls hides every selector the rules look for.
42		ruleDotImport = "dot-import"
43	)
