45	// violation is one place where the source leaves the proxy entry point.
46	type violation struct {
47		File string // slash path from the module root
48		Line int
49		Rule string // "R1".."R4" or ruleDotImport
50		Func string // enclosing func ("Type.Method" or "Func") or package-level name
51	}
52	
53	// String is the report line: file:line: rule (enclosing function).
54	func (v violation) String() string {
55		fn := v.Func
56		if fn == "" {
57			fn = "file scope"
58		}
59		return fmt.Sprintf("%s:%d: %s (%s)", v.File, v.Line, v.Rule, fn)
60	}
