121	// scanner holds what one file's imports resolve to.
122	type scanner struct {
123		fset      *token.FileSet
124		file      string
125		names     map[string]string // local package name -> import path, for the two watched packages
126		importsHT bool              // the file imports net/http, under any name
127		out       []violation
128	}
129	
130	// scanSource parses src as the file name (a slash path from the module root) and
131	// returns its violations ordered by line, then rule.
132	func scanSource(name string, src []byte) ([]violation, error) {
133		fset := token.NewFileSet()
134		f, err := parser.ParseFile(fset, name, src, parser.SkipObjectResolution)
135		if err != nil {
136			return nil, err
137		}
138		s := &scanner{fset: fset, file: name, names: map[string]string{}}
139		s.resolveImports(f)
140	
141		for _, decl := range f.Decls {
142			switch d := decl.(type) {
143			case *ast.FuncDecl:
144				s.inspect(d, funcName(d))
145			case *ast.GenDecl:
146				for _, spec := range d.Specs {
147					switch sp := spec.(type) {
148					case *ast.ValueSpec:
149						s.inspect(sp, sp.Names[0].Name)
150					case *ast.TypeSpec:
151						s.inspect(sp, sp.Name.Name)
152					}
153				}
154			}
155		}
156		slices.SortStableFunc(s.out, func(a, b violation) int {
157			if a.Line != b.Line {
158				return a.Line - b.Line
159			}
160			return strings.Compare(a.Rule, b.Rule)
161		})
162		return s.out, nil
163	}
164	
165	// resolveImports records the local name of net/http and crypto/tls, alias
166	// included, and reports a dot import of either.
167	func (s *scanner) resolveImports(f *ast.File) {
168		for _, imp := range f.Imports {
169			p, err := strconv.Unquote(imp.Path.Value)
170			if err != nil || (p != guardHTTPPath && p != guardTLSPath) {
171				continue
172			}
173			if p == guardHTTPPath {
174				s.importsHT = true
175			}
176			local := path.Base(p)
177			if imp.Name != nil {
178				local = imp.Name.Name
179			}
180			switch local {
181			case "_":
182				continue
183			case ".":
184				s.add(imp.Pos(), ruleDotImport, "import")
185				continue
186			}
187			s.names[local] = p
188		}
189	}
190	
191	func (s *scanner) add(pos token.Pos, rule, fn string) {
192		s.out = append(s.out, violation{File: s.file, Line: s.fset.Position(pos).Line, Rule: rule, Func: fn})
193	}
194	
195	// isSel reports whether e is pkg.Name for the imported package at pkgPath, under
196	// whatever local name the file gave it; with no names, any selector of it.
197	func (s *scanner) isSel(e ast.Expr, pkgPath string, names ...string) bool {
198		sel, ok := e.(*ast.SelectorExpr)
199		if !ok {
200			return false
201		}
202		id, ok := sel.X.(*ast.Ident)
203		if !ok || s.names[id.Name] != pkgPath {
204			return false
205		}
206		return len(names) == 0 || slices.Contains(names, sel.Sel.Name)
207	}
208	
209	// valueOfType reports a type expression that builds a transport or a dialer by
210	// value: http.Transport (R1) or tls.Dialer (R4).
211	func (s *scanner) valueOfType(typ ast.Expr, pos token.Pos, fn string) {
212		switch {
213		case s.isSel(typ, guardHTTPPath, "Transport"):
214			s.add(pos, "R1", fn)
215		case s.isSel(typ, guardTLSPath, "Dialer"):
216			s.add(pos, "R4", fn)
217		}
218	}
219	
220	// inspect walks one top-level declaration; closures belong to the declaration
221	// that holds them.
222	func (s *scanner) inspect(node ast.Node, fn string) {
223		ast.Inspect(node, func(n ast.Node) bool {
224			switch n := n.(type) {
225			case *ast.CompositeLit:
226				if n.Type != nil {
227					s.valueOfType(n.Type, n.Pos(), fn)
228				}
229			case *ast.CallExpr:
230				if id, ok := n.Fun.(*ast.Ident); ok && id.Name == "new" && len(n.Args) == 1 {
231					s.valueOfType(n.Args[0], n.Pos(), fn)
232				}
233			case *ast.ValueSpec:
234				if n.Type != nil {
235					s.valueOfType(n.Type, n.Pos(), fn)
236				}
237			case *ast.SelectorExpr:
238				if s.isSel(n, guardHTTPPath, "DefaultTransport") {
239					s.add(n.Pos(), "R2", fn)
240				}
241				if s.isSel(n, guardTLSPath, "Dial", "DialWithDialer", "Client") {
242					s.add(n.Pos(), "R4", fn)
243				}
244			case *ast.AssignStmt:
245				if s.importsHT && n.Tok == token.ASSIGN {
246					for _, lhs := range n.Lhs {
247						if sel, ok := lhs.(*ast.SelectorExpr); ok && sel.Sel.Name == "Proxy" {
248							s.add(n.Pos(), "R3", fn)
249						}
250					}
251				}
252			case *ast.KeyValueExpr:
253				if id, ok := n.Key.(*ast.Ident); ok && s.importsHT && id.Name == "Proxy" {
254					s.add(n.Pos(), "R3", fn)
255				}
256			}
257			return true
258		})
259	}
260	
261	// funcName is "Func" or "Type.Method", without the pointer or the type
262	// parameters of the receiver.
263	func funcName(d *ast.FuncDecl) string {
264		if d.Recv == nil || len(d.Recv.List) == 0 {
265			return d.Name.Name
266		}
267		return receiverName(d.Recv.List[0].Type) + "." + d.Name.Name
268	}
269	
270	func receiverName(e ast.Expr) string {
271		switch t := e.(type) {
272		case *ast.StarExpr:
273			return receiverName(t.X)
274		case *ast.ParenExpr:
275			return receiverName(t.X)
276		case *ast.IndexExpr:
277			return receiverName(t.X)
278		case *ast.IndexListExpr:
279			return receiverName(t.X)
280		case *ast.Ident:
281			return t.Name
282		}
283		return ""
284	}
