305	// scanTree scans every non-test .go file under root. The excluded directories
306	// are matched on the names of the entries below root, never on root's own
307	// absolute path: a checkout that lives under .worktrees is still scanned.
308	// It also returns the number of files read.
309	func scanTree(root string) ([]violation, int, error) {
310		var all []violation
311		files := 0
312		err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
313			if err != nil {
314				return err
315			}
316			rel, err := filepath.Rel(root, p)
317			if err != nil {
318				return err
319			}
320			rel = filepath.ToSlash(rel)
321			if d.IsDir() {
322				if rel != "." && (slices.Contains(guardExcludedDirs, d.Name()) || rel == guardOwnDir) {
323					return filepath.SkipDir
324				}
325				return nil
326			}
327			if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
328				return nil
329			}
330			src, err := os.ReadFile(p)
331			if err != nil {
332				return err
333			}
334			vs, err := scanSource(rel, src)
335			if err != nil {
336				return err
337			}
338			files++
339			all = append(all, vs...)
340			return nil
341		})
342		return all, files, err
343	}
